-- Tables owned by case-service for admin letter generation.

-- One row per letter type. Generate takes SELECT ... FOR UPDATE on the row
-- for its type, which serialises generation per type.
CREATE TABLE letter_type_lock (
  letter_type VARCHAR(40) PRIMARY KEY
);

-- Identity columns use the SQL-standard GENERATED BY DEFAULT AS IDENTITY
-- (H2, PostgreSQL, Oracle 12c+, DB2). Real DB may differ: e.g. SQL Server
-- uses IDENTITY(1,1), MySQL uses AUTO_INCREMENT.
CREATE TABLE letter_run (
  run_id                BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  letter_type           VARCHAR(40)  NOT NULL,
  claim_submitted_date  DATE         NOT NULL,
  status                VARCHAR(20)  NOT NULL,  -- GENERATING | COMPLETE | NEEDS_ATTENTION
  visibility            VARCHAR(20)  NOT NULL,  -- STAFF_ONLY | STAFF_AND_EXTERNAL
  total_count           INT          NOT NULL,
  generated_count       INT          NOT NULL,
  last_progress_at      TIMESTAMP    NOT NULL,
  completed_at          TIMESTAMP,
  requested_by          VARCHAR(100) NOT NULL,
  requested_at          TIMESTAMP    NOT NULL,
  released_by           VARCHAR(100),
  released_at           TIMESTAMP,
  idempotency_key       VARCHAR(64)  NOT NULL UNIQUE
);

-- Fixed membership of a run, recorded once at generate time. The queue is
-- populated from these rows, and progress and visibility join on
-- (app_id, letter_type) because the queue has no row ID to link to.
CREATE TABLE letter_run_item (
  run_id       BIGINT       NOT NULL REFERENCES letter_run(run_id),
  app_id       VARCHAR(40)  NOT NULL,
  letter_type  VARCHAR(40)  NOT NULL,
  queue_key    VARCHAR(100) NOT NULL,
  created_at   TIMESTAMP    NOT NULL,
  PRIMARY KEY (run_id, app_id)
);
CREATE INDEX ix_item_app_type ON letter_run_item (app_id, letter_type, created_at DESC);

CREATE TABLE letter_run_audit (
  audit_id  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  run_id    BIGINT       NOT NULL REFERENCES letter_run(run_id),
  action    VARCHAR(20)  NOT NULL,   -- GENERATE | RELEASE | REVOKE
  actor     VARCHAR(100) NOT NULL,
  at        TIMESTAMP    NOT NULL
);
